const [claude, astra] = await Promise.allSettled([
  tools.opencode.models({ query: 'claude', limit: 15 }),
  tools.opencode.models({ query: 'astra', limit: 15 }),
]);
const fmt = (r) => r.status === 'fulfilled'
  ? r.value.providers.flatMap(p => p.models.map(m => `${p.id}/${m.id} — ${m.name} (in: $${m.cost?.[0]?.input ?? '?'}, out: $${m.cost?.[0]?.output ?? '?'})`))
  : [`ERROR: ${r.reason}`];
return { claude: fmt(claude), astra: fmt(astra) };

